DROP TABLE IF EXISTS domain_relation CASCADE;
DROP TABLE IF EXISTS attribute CASCADE;
DROP TABLE IF EXISTS "option" CASCADE;
DROP TABLE IF EXISTS domain CASCADE;

CREATE TABLE domain (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code VARCHAR(255) NOT NULL,
  description VARCHAR(255) NOT NULL,
  created_at TIMESTAMP NOT NULL,
  updated_at TIMESTAMP,
  status BOOLEAN NOT NULL
);

CREATE TABLE attribute (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code VARCHAR(255) NOT NULL,
  description VARCHAR(255) NOT NULL,
  created_at TIMESTAMP NOT NULL,
  updated_at TIMESTAMP,
  status BOOLEAN NOT NULL,
  type VARCHAR(255) NOT NULL,
  mandatory BOOLEAN NOT NULL,
  domain_id BIGINT NOT NULL REFERENCES domain(id)
);

CREATE TABLE "option" (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code VARCHAR(255) NOT NULL,
  description VARCHAR(255) NOT NULL,
  created_at TIMESTAMP NOT NULL,
  updated_at TIMESTAMP,
  status BOOLEAN NOT NULL,
  "values" JSONB NOT NULL,
  attribute_id BIGINT NOT NULL UNIQUE REFERENCES attribute(id)
);

CREATE TABLE domain_relation (
  domain_id BIGINT NOT NULL REFERENCES domain(id),
  related_domain_id BIGINT NOT NULL REFERENCES domain(id),
  CONSTRAINT domain_relation_pk PRIMARY KEY (domain_id, related_domain_id),
  CONSTRAINT domain_relation_not_self CHECK (domain_id <> related_domain_id)
);

