INSERT INTO "option" (code, description, "values", attribute_id, status, created_at, updated_at)
SELECT 'DIFTERIA__TP_NOTIFICACAO', 'Options for DIFTERIA__TP_NOTIFICACAO', '{"options":[{"value":"1","label":"Negativa"},{"value":"2","label":"Individual"},{"value":"3","label":"Surto"},{"value":"4","label":"Agregado"}]}'::jsonb, a.id, TRUE, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM attribute a JOIN domain d ON d.id = a.domain_id WHERE d.code = 'DIFTERIA' AND a.code = 'tp_notificacao'
  AND NOT EXISTS (SELECT 1 FROM "option" o WHERE o.code = 'DIFTERIA__TP_NOTIFICACAO');
