FROM attribute a JOIN domain d ON d.id = a.domain_id
WHERE o.code = 'DIFTERIA__TP_NOTIFICACAO' AND d.code = 'DIFTERIA' AND a.code = 'tp_notificacao'
  AND o.attribute_id IS NULL;

